48	  };
49	
50	  // display_nameがNULLの場合は「名無しさん」にフォールバック
51	  if (result.user && !result.user.display_name) {
52	    result.user.display_name = '名無しさん';
53	  }
54	
55	  return {
56	    success: result.success,
57	    message: result.message,
58	    user: result.user ? { display_name: result.user.display_name } : null,
59	    type: result.type,
60	  };
61	}
62	
