208	                    width={256}
209	                    height={256}
210	                    alt="QR Code"
211	                    data-ai-hint="qr code"
212	                    priority
213	                />
214	            </div>
215	            <p className="mt-4 text-xl max-w-md">スマートフォンでQRコードを読み取り登録を完了してください。</p>
216	            <div className="mt-4 flex items-center gap-2 bg-gray-800 px-4 py-2 rounded-lg max-w-2xl">
217	                <p className="text-sm text-gray-300 font-mono break-all">{url}</p>
218	                <Button variant="ghost" size="icon" onClick={handleCopy} className="flex-shrink-0">
219	                    <Copy className="h-5 w-5" />
220	                </Button>
221	            </div>
222	            <QrTimer qrExpiry={qrExpiry} onExpire={onExpire} />
223	            <p className="text-sm text-gray-500 mt-4">※QR読み取り後、この画面は自動的に戻ります</p>
224	        </div>
225	    );
226	});
227	QrScreen.displayName = 'QrScreen';
