229	const ProcessingScreen = memo(({ state }: { state: 'loading' | 'processing' }) => (
230	    <div className="text-center flex flex-col items-center">
231	        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-gray-400"></div>
232	        <p className="text-4xl text-gray-400 mt-8">{state === 'loading' ? '読み込み中...' : '処理中...'}</p>
233	    </div>
234	));
